    <h1>User Input Logger</h1>
    <form id="inputForm">
        <label for="userInput">Enter something:</label>
        <input type="text" id="userInput" name="userInput" required>
        <button type="submit">Submit</button>
    </form>
    <p id="responseMessage"></p>

    <script>
        const form = document.getElementById('inputForm');
        const responseMessage = document.getElementById('responseMessage');

        form.addEventListener('submit', async (event) => {
            event.preventDefault();
            const userInput = document.getElementById('userInput').value;

            try {
                const response = await fetch('/log', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                    },
                    body: JSON.stringify({ userInput }),
                });

                if (response.ok) {
                    responseMessage.textContent = 'Input logged successfully!';
                } else {
                    responseMessage.textContent = 'Failed to log input.';
                }
            } catch (error) {
                responseMessage.textContent = 'An error occurred.';
                console.error(error);
            }
        });
    </script>
</body>
</html>
```

---

### Backend: `server.js`
```javascript
const express = require('express');
const fs = require('fs');
const path = require('path');

const app = express();
const PORT = 3000;

// Middleware to parse JSON requests
app.use(express.json());

// Serve static files (frontend)
app.use(express.static(path.join(__dirname, 'public')));

// Endpoint to log user input
app.post('/log', (req, res) => {
    const { userInput } = req.body;

    if (!userInput) {
        return res.status(400).send('Invalid input');
    }

    const logEntry = `${new Date().toISOString()} - ${userInput}\n`;

    // Append the input to a local file
    fs.appendFile('user-inputs.txt', logEntry, (err) => {
        if (err) {
            console.error('Error writing to file:', err);
            return res.status(500).send('Failed to log input');
        }
        res.status(200).send('Input logged successfully');
    });
});

// Start the server
app.listen(PORT, () => {
    console.log(`Server is running on http://localhost:${PORT}`);
});
```

---

### Directory Structure
```
project/
├── public/
│   └── index.html
├── server.js
└── user-inputs.txt
```

---

### Instructions to Run the Application
1. **Install Node.js**: Ensure Node.js is installed on your system.
2. **Initialize the Project**:
   - Create a new directory and navigate to it.
   - Run `npm init -y` to initialize a Node.js project.
