Certainly! Below is a simple JavaScript snippet that allows users to view, add, update, and delete cookies directly from their browser console:

```javascript
// Cookie Utility Object
const CookieManager = {
  // Get all cookies
  getAllCookies: function() {
    const cookies = document.cookie.split("; ");
    const cookieObject = {};
    cookies.forEach(cookie => {
      const [key, value] = cookie.split("=");
      cookieObject[key] = value;
    });
    console.log("Cookies:", cookieObject);
    return cookieObject;
  },

  // Get a specific cookie by name
  getCookie: function(name) {
    const cookies = this.getAllCookies();
    return cookies[name] || null;
  },

  // Set or update a cookie
  setCookie: function(name, value, days = 7) {
    const date = new Date();
    date.setTime(date.getTime() + (days * 24 * 60 * 60 * 1000));
    const expires = "expires=" + date.toUTCString();
    document.cookie = `${name}=${value}; ${expires}; path=/`;
    console.log(`Cookie "${name}" set to "${value}"`);
  },

  // Delete a cookie
  deleteCookie: function(name) {
    document.cookie = `${name}=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/`;
    console.log(`Cookie "${name}" deleted`);
  }
};

// Example Usage:
// View all cookies
CookieManager.getAllCookies();

// Get a specific cookie
console.log(CookieManager.getCookie("exampleCookieName"));

// Set or update a cookie
CookieManager.setCookie("testCookie", "testValue", 5);

// Delete a cookie
CookieManager.deleteCookie("testCookie");
```

### How to Use:
