```javascript
// Import required modules
const express = require('express');
const bcrypt = require('bcrypt');
const jwt = require('jsonwebtoken');
const bodyParser = require('body-parser');

const app = express();
app.use(bodyParser.json());

// Secret key for JWT
const JWT_SECRET = 'your_secret_key_here'; // Replace with a strong secret key

// Mock database (replace with a real database in production)
const users = [];

// Register endpoint
app.post('/register', async (req, res) => {
    const { username, password } = req.body;

    // Check if user already exists
    const existingUser = users.find(user => user.username === username);
    if (existingUser) {
        return res.status(400).json({ message: 'User already exists' });
    }

    // Hash the password
    const hashedPassword = await bcrypt.hash(password, 10);

    // Save user to the database
    users.push({ username, password: hashedPassword });
    res.status(201).json({ message: 'User registered successfully' });
});

// Login endpoint
app.post('/login', async (req, res) => {
    const { username, password } = req.body;

    // Find user in the database
    const user = users.find(user => user.username === username);
    if (!user) {
        return res.status(400).json({ message: 'Invalid username or password' });
    }

    // Compare passwords
    const isPasswordValid = await bcrypt.compare(password, user.password);
    if (!isPasswordValid) {
        return res.status(400).json({ message: 'Invalid username or password' });
    }

    // Generate JWT token
    const token = jwt.sign({ username: user.username }, JWT_SECRET, { expiresIn: '1h' });
    res.status(200).json({ message: 'Login successful', token });
});

// Middleware to authenticate JWT
const authenticateToken = (req, res, next) => {
    const authHeader = req.headers['authorization'];
    const token = authHeader && authHeader.split(' ')[1];

    if (!token) {
        return res.status(401).json({ message: 'Access denied' });
    }

    jwt.verify(token, JWT_SECRET, (err, user) => {
        if (err) {
            return res.status(403).json({ message: 'Invalid token' });
        }
        req.user = user;
        next();
    });
};

// Protected route example
app.get('/protected', authenticateToken, (req, res) => {
    res.status(200).json({ message: `Hello, ${req.user.username}! You have access to this protected route.` });
});

// Start the server
const PORT = 3000;
app.listen(PORT, () => {
    console.log(`Server is running on http://localhost:${PORT}`);
});
```

### Key Features:
1. **Password Hashing**: Uses `bcrypt` to securely hash passwords before storing them.
2. **JWT Authentication**: Generates a token upon successful login, which is used for session management.
3. **Middleware for Protected Routes**: Ensures that only authenticated users can access certain routes.
4. **Basic Error Handling**: Provides meaningful error messages for common issues.

### Notes:
- Replace `your_secret_key_here` with a strong, unique secret key for JWT.
- In production, use a real database (e.g., MongoDB, PostgreSQL) instead of the mock `users` array.
- Use HTTPS to secure communication between the client and server.
- Consider implementing additional security measures like rate limiting, account lockout after multiple failed login attempts, and input validation.

