    const result = await response.json();
    if (!result.publicUrl) {
      throw new Error("Public URL not returned by the server.");
    }

    // Return the public URL for sharing
    return result.publicUrl;
  } catch (error) {
    console.error("Error uploading file:", error);
    throw error;
  }
}

