const sqlite3 = require('sqlite3').verbose();
const path = require('path');

// Initialize the database
const dbPath = path.join(__dirname, 'login_attempts.db');
const db = new sqlite3.Database(dbPath);

// Create the table if it doesn't exist
db.serialize(() => {
  db.run(`
    CREATE TABLE IF NOT EXISTS login_attempts (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      username TEXT NOT NULL,
      timestamp TEXT NOT NULL
    )
  `);
});

// Function to log a login attempt
function logLoginAttempt(username, timestamp) {
  return new Promise((resolve, reject) => {
    const query = `INSERT INTO login_attempts (username, timestamp) VALUES (?, ?)`;
    db.run(query, [username, timestamp], function (err) {
      if (err) reject(err);
      else resolve();
    });
  });
}

// Function to retrieve all login attempts
function getLoginAttempts() {
  return new Promise((resolve, reject) => {
    const query = `SELECT * FROM login_attempts ORDER BY timestamp DESC`;
    db.all(query, [], (err, rows) => {
      if (err) reject(err);
      else resolve(rows);
    });
  });
}

module.exports = { logLoginAttempt, getLoginAttempts };
